To optimize the solution for handling a large load efficiently, we will implement the Sieve of Eratosthenes algorithm to generate prime numbers up to 200. Then, we will use a recursive function to check if each prime number is part of the Factorial sequence. Finally, we will count and display the prime numbers found in ascending order.

Here's the Python code that accomplishes this task:

```python
def sieve_of_eratosthenes(n):
    primes = [True] * (n + 1)
    primes[0] = primes[1] = False

    p = 2
    while p * p <= n:
        if primes[p]:
            for i in range(p * p, n + 1, p):
                primes[i] = False
        p += 1

    return [i for i in range(2, n + 1) if primes[i]]

def is_prime(n, i=2):
    if n <= 2:
        return n == 2
    if n % i == 0:
        return False
    if i * i > n:
        return True
    return is_prime(n, i + 1)

def find_primes_in_factorial_sequence(n, primes, result=[]):
    if n == 0:
        return result

    if is_prime(n) and n in primes:
        result.append(n)

    return find_primes_in_factorial_sequence(n - 1, primes, result)

# Generate prime numbers up to 200 using Sieve of Eratosthenes
primes_up_to_200 = sieve_of_eratosthenes(200)

# Find prime numbers in the Factorial sequence
prime_numbers_in_factorial = find_primes_in_factorial_sequence(200, primes_up_to_200)

# Display the count and prime numbers in ascending order
print(f"Total count of prime numbers in Factorial sequence: {len(prime_numbers_in_factorial)}")
print("Prime numbers in Factorial sequence:")
print(sorted(prime_numbers_in_factorial))
```

