```javascript
function capitalizeWords(str) {
  // Remove punctuation and whitespace
  str = str.replace(/[^\w\s]/gi, "");
  // Split the string into words
  var words = str.split(/\s+/);
  // Loop through the words
  for (var i = 0; i < words.length; i++) {
    // Capitalize the first and last letter of the word
    words[i] = words[i].charAt(0).toUpperCase() + words[i].slice(1);
    // If there is an odd number of characters in the word, capitalize the middle character
    if (i + 1 === words.length) {
      words[i] = words[i].charAt(0).toUpperCase() + words[i].slice(1) + words[i].charAt(0).toLowerCase();
    }
  }
  // Join the words back into a string
  return words.join(" ");
}
```

