        return node != null && node.isEnd();
    }

    // Method to delete a word from the Trie
    public void delete(String word) {
        delete(root, word, 0);
    }

    // Helper method to delete a word from the Trie
    private boolean delete(TrieNode node, String word, int index) {
        if (index == word.length()) {
            if (!node.isEnd()) {
                return false;
            }
            node.setEnd(false);
            return node.isEmpty();
        }
        char currentChar = word.charAt(index);
        TrieNode childNode = node.get(currentChar);
        if (childNode == null) {
            return false;
        }
        boolean shouldDeleteCurrentNode = delete(childNode, word, index + 1) && !childNode.isEnd();
        if (shouldDeleteCurrentNode) {
            node.remove(currentChar);
            return node.isEmpty();
        }
        return false;
    }

    // Helper method to search prefix in the Trie
