import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class ReverseWordsMultiThreaded {

    private static final List<String> excludedWords = Arrays.asList("of", "and", "in", "on", "for", "to", "with");

    public static void main(String[] args) {
        String sentence = "Hello world of artificial intelligence";
        String[] words = sentence.split(" ");

        ExecutorService executor = Executors.newFixedThreadPool(words.length);

        for (String word : words) {
            executor.execute(() -> {
                if (!excludedWords.contains(word.toLowerCase())) {
                    System.out.print(reverseWord(word) + " ");
                } else {
                    System.out.print(word + " ");
                }
            });
        }

        executor.shutdown();
    }

    private static String reverseWord(String word) {
        char[] charArray = word.toCharArray();
        int start = 0;
        int end = charArray.length - 1;

        while (start < end) {
            if (Character.isLetter(charArray[start]) && Character.isLetter(charArray[end])) {
                char temp = charArray[start];
                charArray[start] = charArray[end];
                charArray[end] = temp;
                start++;
                end--;
            } else if (!Character.isLetter(charArray[start])) {
                start++;
            } else {
                end--;
            }
        }

        return new String(charArray);
    }
}
