To rotate the matrix in-place, we can perform the rotation layer by layer, starting from the outermost layer to the innermost layer. Here's the algorithm in JavaScript:

```javascript
function rotateMatrix(matrix) {
    if (!matrix || matrix.length === 0 || matrix.length !== matrix[0].length) {
        return;
    }

    const n = matrix.length;

    // Traverse the matrix layer by layer
    for (let layer = 0; layer < Math.floor(n / 2); layer++) {
        const first = layer;
        const last = n - 1 - layer;

        for (let i = first; i < last; i++) {
            const offset = i - first;
            const top = matrix[first][i];

            // Left -> Top
            matrix[first][i] = matrix[last - offset][first];

            // Bottom -> Left
            matrix[last - offset][first] = matrix[last][last - offset];

            // Right -> Bottom
            matrix[last][last - offset] = matrix[i][last];

            // Top -> Right
            matrix[i][last] = top;
        }
    }
}

